import type { Href } from 'expo-router';

import type { BillingTermMonths } from '@stepwhere/types';

// Billing screens live under src/app/(app)/billing. Hrefs are cast because the
// typed-routes manifest is regenerated by the dev server, not by tsc.

/** Where the Status screen's Done goes: back to the app, or back to Subscription. */
export type BillingReturnTo = 'app' | 'subscription';

export const billingRoutes = {
  choosePlan: () => '/billing/choose-plan' as Href,
  review: (deviceIds: string[], termMonths: BillingTermMonths) => ({
    pathname: '/billing/review',
    params: { deviceIds: deviceIds.join(','), termMonths: String(termMonths) },
  }) as unknown as Href,
  status: (checkoutId: string, returnTo: BillingReturnTo) => ({
    pathname: '/billing/status',
    params: { checkoutId, returnTo },
  }) as unknown as Href,
  subscription: () => '/billing/subscription' as Href,
  addShoes: (deviceId?: string) => (deviceId
    ? { pathname: '/billing/add-shoes', params: { deviceId } }
    : '/billing/add-shoes') as unknown as Href,
  invoices: () => '/billing/invoices' as Href,
  invoice: (chargeId: string) => ({ pathname: '/billing/invoice', params: { chargeId } }) as unknown as Href,
};
